svg.script:
(function(){'use strict';
const NS='http://www.w3.org/2000/svg',svg=document.documentElement,$=i=>document.getElementById(i),PI=Math.PI;
const cl=(v,a,b)=>v<a?a:v>b?b:v,sm=t=>{t=cl(t,0,1);return t*t*(3-2*t)},rnd=(a,b)=>a+Math.random()*(b-a),mx3=(a,b,t)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];
const nrm=a=>{const l=Math.hypot(a[0],a[1],a[2])||1;return[a[0]/l,a[1]/l,a[2]/l]},sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]],crs=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const lerpA=(a,b,t)=>{let d=(b-a)%(PI*2);if(d>PI)d-=PI*2;if(d<-PI)d+=PI*2;return a+d*t};
const E=(t,a,p)=>{const n=document.createElementNS(NS,t);for(const k in a)n.setAttribute(k,a[k]);if(p)p.appendChild(n);return n};
let VW=1280,VH=800,UID=0;const DEFS=$('defs'),SC=$('scene'),HUDG=$('hud');
// ===== PROJECTION =====
const CAM={eye:[0,1.6,-6],tg:[0,1.2,0],fov:50,ang:0,yaw:0,pitch:.2,view:0,zoom:1,shake:0};
const VIEWS=['CLASSIC SIDE','WIDE ARENA','OVER SHOULDER','LOW CINEMATIC','TOP DOWN','FREE ORBIT'];
let EYE=[0,0,0],FW=[0,0,1],RT=[1,0,0],UP=[0,1,0],PPM=500,SX=0,SY=0,SZ=0;
function camSetup(){EYE=CAM.eye.slice();if(CAM.shake>.002){for(let i=0;i<3;i++)EYE[i]+=rnd(-1,1)*CAM.shake;CAM.shake*=.88}
 FW=nrm(sub(CAM.tg,EYE));RT=nrm(crs(FW,[0,1,0]));UP=crs(RT,FW);PPM=VH/2/Math.tan(CAM.fov*PI/360)}
function pr(x,y,z){const a=x-EYE[0],b=y-EYE[1],c=z-EYE[2],zc=a*FW[0]+b*FW[1]+c*FW[2];if(zc<.2)return 0;const k=PPM/zc;
 SX=VW/2+(a*RT[0]+b*RT[1]+c*RT[2])*k;SY=VH/2-(a*UP[0]+b*UP[1]+c*UP[2])*k;SZ=zc;return 1}
// ===== DOT LAYERS: every particle is a round-cap vector point; each bucket = 1 path + 3 <use> (halo, sphere body, specular gleam) =====
function Layer(par){const g=E('g',{'stroke-linecap':'round'},par),m=new Map();let fr=0;
 return{g,beg(){fr++},
 get(key,col,w,op,gl){let o=m.get(key);if(!o){const id='q'+(++UID);o={a:[],f:0,p:E('path',{id:id,fill:'none'},DEFS),u:[0,1,2].map(()=>E('use',{href:'#'+id,fill:'none'},g)),vis:1};m.set(key,o)}
  if(o.f!==fr){o.f=fr;o.a.length=0;o.col=col;o.w=w;o.op=op;o.gl=gl}return o.a},
 end(){for(const o of m.values()){if(o.f!==fr||!o.a.length){if(o.vis){o.u.forEach(u=>u.setAttribute('display','none'));o.vis=0}continue}
  if(!o.vis){o.u.forEach(u=>u.removeAttribute('display'));o.vis=1}
  o.p.setAttribute('d',o.a.join(''));const w=o.w,c=o.col,s='rgb('+(c[0]|0)+','+(c[1]|0)+','+(c[2]|0)+')',h=o.u[0],b=o.u[1],g2=o.u[2];
  h.setAttribute('stroke',s);h.setAttribute('stroke-width',(w*2.5).toFixed(1));h.setAttribute('stroke-opacity',o.gl?(.17*o.op).toFixed(2):0);
  b.setAttribute('stroke',s);b.setAttribute('stroke-width',w.toFixed(1));b.setAttribute('stroke-opacity',o.op.toFixed(2));
  if(w>=3){g2.setAttribute('stroke','rgb('+Math.min(255,c[0]*.5+150|0)+','+Math.min(255,c[1]*.5+150|0)+','+Math.min(255,c[2]*.5+150|0)+')');g2.setAttribute('stroke-width',(w*.4).toFixed(1));
   g2.setAttribute('stroke-opacity',(o.op*.8).toFixed(2));g2.setAttribute('transform','translate('+(-w*.17).toFixed(1)+','+(-w*.17).toFixed(1)+')')}else g2.setAttribute('stroke-opacity',0)}}}}
const dot=(x,y)=>'M'+x.toFixed(1)+' '+y.toFixed(1)+'h.1';
const sceneL={};['bg','ground','floor','w0','w1','w2','f0','f1','fx'].forEach(k=>{sceneL[k]=E('g',{},SC)});
const skyG=E('g',{},sceneL.bg),sunC=E('circle',{fill:'url(#glo)'},skyG),moonC=E('circle',{fill:'url(#glo)'},skyG),sunD=E('circle',{},skyG),moonD=E('circle',{fill:'#dfe8ff'},skyG);
const starL=Layer(sceneL.bg),cloudL=Layer(sceneL.bg),mtnP=[0,1,2].map(()=>E('path',{},sceneL.bg)),cityP=E('path',{},sceneL.bg),winL=Layer(sceneL.bg);
const gndP=[0,1,2,3].map(()=>E('path',{},sceneL.ground)),floorL=Layer(sceneL.floor),worldL=[Layer(sceneL.w0),Layer(sceneL.w1),Layer(sceneL.w2)],fxL=Layer(sceneL.fx);
const fL=[0,1].map(i=>[0,1,2].map(()=>Layer(E('g',{},sceneL['f'+i]))));
// ===== ARCHETYPES =====
const ARCH=[
{n:'OPERATOR',S:1,hp:100,spd:1,dmg:1,reach:1,aggr:.5,ideal:1.5,pw:['plasma','nova'],f:[.16,.44,.47],f2:[.12,.3,.34],e:[.15,1.15,.95],a:[1.2,.88,.16],y:[.2,1.4,1.2],hot:[1.4,1.2,.5],sh:.012,rise:0,rm:[1,1]},
{n:'EMBER BRUTE',S:1.22,hp:130,spd:.85,dmg:1.25,reach:1.1,aggr:.65,ideal:1.6,pw:['fire','pillar'],f:[.55,.12,.04],f2:[.9,.3,.05],e:[1.5,.8,.1],a:[1.6,1.1,.3],y:[1.8,1.6,.5],hot:[1.6,.8,.2],sh:.02,rise:1,rm:[1.15,1.2]},
{n:'FROST WRAITH',S:1.12,hp:90,spd:1.05,dmg:.9,reach:1.15,aggr:.5,ideal:3,pw:['shards','zero'],f:[.35,.62,.75],f2:[.7,.9,1],e:[.7,1.5,1.7],a:[1.5,1.7,1.9],y:[1.8,1.8,2],hot:[.7,1.5,1.8],sh:.006,rise:.4,rm:[.8,.8]},
{n:'VOLT STRIKER',S:.97,hp:85,spd:1.4,dmg:.85,reach:.95,aggr:.8,ideal:1.4,pw:['bolt','dash'],f:[.7,.62,.12],f2:[.25,.35,.9],e:[1.7,1.6,.5],a:[.5,.9,2],y:[2,2,1.5],hot:[1.8,1.8,1],sh:.02,rise:0,rm:[1,.9]},
{n:'VOID WEAVER',S:1.1,hp:100,spd:.95,dmg:1,reach:1.05,aggr:.55,ideal:2.6,pw:['orb','horizon'],f:[.22,.06,.34],f2:[.5,.1,.6],e:[1.1,.25,1.5],a:[1.7,.5,1.9],y:[2,1.2,2],hot:[1.5,.4,1.8],sh:.014,rise:.3,rm:[.9,1]},
{n:'STONE GOLEM',S:1.4,hp:170,spd:.62,dmg:1.5,reach:1.15,aggr:.5,ideal:1.7,pw:['boulder','quake'],f:[.3,.28,.22],f2:[.2,.4,.15],e:[.5,1.1,.35],a:[.9,1.6,.5],y:[1.8,1.8,.6],hot:[1,1.6,.5],sh:.003,rise:.2,rm:[1.2,1.25]}];
const PW={plasma:{n:'PLASMA SURGE',cost:25,dur:.75,fx:.36,an:'c'},nova:{n:'NOVA BURST',cost:50,dur:.85,fx:.3,an:'r'},fire:{n:'FIREBALL',cost:25,dur:.8,fx:.4,an:'c'},pillar:{n:'INFERNO PILLAR',cost:50,dur:.95,fx:.35,an:'r'},
shards:{n:'ICE SHARDS',cost:25,dur:.7,fx:.34,an:'c'},zero:{n:'ABSOLUTE ZERO',cost:50,dur:.95,fx:.4,an:'r'},bolt:{n:'BOLT STRIKE',cost:25,dur:.55,fx:.25,an:'c'},dash:{n:'THUNDER DASH',cost:40,dur:.6,fx:.18,an:'c'},
orb:{n:'SINGULARITY',cost:30,dur:.85,fx:.4,an:'c'},horizon:{n:'EVENT HORIZON',cost:55,dur:1,fx:.4,an:'r'},boulder:{n:'BOULDER THROW',cost:30,dur:1,fx:.5,an:'r'},quake:{n:'TECTONIC QUAKE',cost:50,dur:1.1,fx:.5,an:'r'}};
const TIERS=[450,700,1100,1600,2300,3200],COARSE=!!(window.matchMedia&&matchMedia('(pointer:coarse)').matches);let tier=COARSE?1:2;
// ===== PARTICLE BODY BUILDER =====
// joints: 0 hips 1 mid 2 chest 3 head 4 lSh 5 rSh 6 lEl 7 rEl 8 lHand 9 rHand 10 lHip 11 rHip 12 lKn 13 rKn 14 lAn 15 rAn 16 lToe 17 rToe
const SEGJ=[[0,1],[1,2],[2,3],[4,6],[5,7],[6,8],[7,9],[10,12],[11,13],[12,14],[13,15],[14,16],[15,17],[9,9]];
const SW=[1,1.2,.15,.4,.4,.35,.35,1,1,.7,.7,.22,.22,.14],R0=[.14,.14,.052,.055,.055,.046,.046,.08,.08,.06,.06,.055,.055,.03],R1=[.15,.15,.05,.05,.05,.04,.04,.065,.065,.045,.045,.05,.05,.026];
function buildCloud(k,N){const A=ARCH[k],o={N,seg:new Int8Array(N),t:new Float32Array(N),th:new Float32Array(N),rad:new Float32Array(N),ci:new Uint8Array(N),rv:new Float32Array(N),kind:new Uint8Array(N),j:new Int8Array(N),ox:new Float32Array(N),oy:new Float32Array(N),oz:new Float32Array(N),n:0};
 const G=[];let tot=0;const add=(w,fn)=>{G.push([w,fn]);tot+=w};
 const rm=s=>s<2?A.rm[0]:A.rm[1];
 for(let s=0;s<14;s++)add(SW[s],(i)=>{o.kind[i]=s===13?1:0;o.seg[i]=s;const t=Math.random();o.t[i]=t;o.th[i]=rnd(0,PI*2);o.rad[i]=(R0[s]+(R1[s]-R0[s])*t)*rm(s);
  const edge=(s>2&&(t<.07||t>.93))||Math.random()<.03;o.ci[i]=s===13?10:edge?10:(Math.min(4,(Math.random()*(Math.sin(t*9+s)*.5+.5)*5)|0)*2+(Math.random()>.5?1:0))});
 const sph=(j,c,r,w,ci,kind,cy)=>add(w,(i)=>{let x,y,z,l;do{x=rnd(-1,1);y=rnd(-1,1);z=rnd(-1,1);l=x*x+y*y+z*z}while(l>1||l<1e-3);l=Math.sqrt(l);o.kind[i]=kind||4;o.j[i]=j;
  o.ox[i]=c[0]+x/l*r;o.oy[i]=c[1]+y/l*r*(cy||1);o.oz[i]=c[2]+z/l*r;o.ci[i]=ci===undefined?Math.min(4,(Math.random()*5)|0)*2:ci});
 const cone=(j,a,b,r,w,ci)=>add(w,(i)=>{const t=Math.random(),th=rnd(0,PI*2),q=r*(1-t);o.kind[i]=4;o.j[i]=j;o.ox[i]=a[0]+(b[0]-a[0])*t+Math.cos(th)*q;o.oy[i]=a[1]+(b[1]-a[1])*t;o.oz[i]=a[2]+(b[2]-a[2])*t+Math.sin(th)*q;o.ci[i]=ci});
 sph(3,[0,.04,0],.105*A.rm[1]*.9,.4,undefined,4,1.1);sph(4,[0,0,0],.085*A.rm[1],.13);sph(5,[0,0,0],.085*A.rm[1],.13);sph(8,[0,0,0],.05*A.rm[1],.1);sph(9,[0,0,0],.05*A.rm[1],.1);
 add(.35,(i)=>{o.kind[i]=4;o.j[i]=3;o.ox[i]=rnd(-.08,.08);o.oy[i]=rnd(.0,.07);o.oz[i]=.1;o.ci[i]=12});// eyes/visor
 if(k===0){}
 if(k===1){[1,-1].forEach(s=>{cone(3,[s*.07,.1,0],[s*.24,.38,.04],.045,.07,11);sph(s>0?5:4,[s*.02,.02,0],.15,.12,10)});}
 if(k===2){for(let i=0;i<5;i++){const a=i*1.26-2.5;cone(3,[Math.sin(a)*.08,.1,Math.cos(a)*.08],[Math.sin(a)*.2,.4+(i%2)*.1,Math.cos(a)*.2],.03,.04,11)}[1,-1].forEach(s=>cone(s>0?7:6,[0,0,0],[s*.35,.4,-.05],.05,.08,11))}
 if(k===3){for(let i=0;i<7;i++)cone(3,[0,.1,0],[Math.sin(i*.9)*.3,.3+.12*(i%3),-.1+Math.cos(i*.9)*.15],.03,.04,11);sph(8,[0,0,0],.09,.1,11);sph(9,[0,0,0],.09,.1,11)}
 if(k===4){add(.18,(i)=>{const th=rnd(0,PI*2);o.kind[i]=4;o.j[i]=3;o.ox[i]=Math.cos(th)*.24;o.oy[i]=.3;o.oz[i]=Math.sin(th)*.24;o.ci[i]=11});
  for(let q=0;q<3;q++)sph(2,[0,0,0],.1,.1,11,2),G[G.length-1][2]=q}
 if(k===5){sph(8,[0,0,0],.16,.16,13);sph(9,[0,0,0],.16,.16,13);sph(4,[0,0,0],.2,.12,13);sph(5,[0,0,0],.2,.12,13);for(let i=0;i<4;i++)cone(2,[(i-1.5)*.08,.0,-.14],[(i-1.5)*.25,.28+.1*(i%2),-.4],.07,.05,13)}
 add(.12+A.rise*.1,(i)=>{o.kind[i]=3;o.th[i]=rnd(0,PI*2);o.rad[i]=.1+Math.random()*.22;o.ci[i]=k===5?13:11});
 let n=0;for(const [w,fn,ex] of G){let c=Math.round(N*w/tot);if(n+c>N)c=N-n;for(let q=0;q<c;q++,n++){fn(n);o.rv[n]=Math.random();if(o.kind[n]===2){o.th[n]=ex===undefined?0:ex*2.094;const ang=o.th[n];const x=o.ox[n],z=o.oz[n];o.ox[n]=x+Math.cos(ang)*.62;o.oz[n]=z+Math.sin(ang)*.62;o.oy[n]=o.oy[n]+.1*(ex||0)}}}
 while(n<N){o.kind[n]=0;o.seg[n]=1;o.t[n]=Math.random();o.th[n]=rnd(0,6.28);o.rad[n]=.1;o.ci[n]=0;o.rv[n]=Math.random();n++}
 o.n=N;return o}
// ===== STATE =====
const M={mode:'FIGHT',twoP:false,round:1,wins:[0,0],timer:99,state:'intro',st:0,opp:1,p1:0,msg:'',stage:0,ladder:1,arena:11.5};
let PAUSED=false,HITSTOP=0,FPS=60,T=0,statusT=0,HELP=true,MENU=window.innerWidth>=900,ptsDrawn=0;
const TOD={hour:12,auto:false,zen:[0,0,0],hor:[0,0,0],sun:[0,0,0],stars:0,mtn:[0,0,0],fog:[0,0,0],amb:[1,1,1],sunDir:[0,1,0],moonDir:[0,-1,0],night:0,floor:[0,1,.8],ground:[.05,.08,.07]};
const KF=[[0,[.01,.015,.05],[.03,.04,.1],[0,0,0],1,[.03,.04,.07],[.02,.03,.06],[.28,.33,.55]],[5.5,[.2,.25,.5],[1,.5,.4],[1.3,.6,.3],.25,[.25,.2,.3],[.5,.35,.35],[.7,.6,.7]],[8,[.25,.5,.9],[.7,.8,1],[1.4,1.2,.9],0,[.25,.35,.5],[.6,.7,.85],[1,1,1]],[12,[.15,.4,.95],[.6,.8,1],[1.5,1.4,1.2],0,[.3,.4,.5],[.6,.75,.9],[1.1,1.1,1.05]],[17,[.25,.45,.85],[.9,.75,.6],[1.5,1.1,.7],0,[.25,.3,.4],[.7,.65,.6],[1,.95,.9]],[19,[.12,.12,.35],[1.2,.4,.2],[1.4,.4,.15],.2,[.15,.1,.18],[.5,.3,.25],[.8,.55,.5]],[21,[.02,.03,.1],[.15,.1,.25],[0,0,0],.9,[.05,.05,.1],[.08,.07,.15],[.3,.35,.6]],[24,[.01,.015,.05],[.03,.04,.1],[0,0,0],1,[.03,.04,.07],[.02,.03,.06],[.28,.33,.55]]];
function updateTOD(){const h=((TOD.hour%24)+24)%24;let i=0;while(i<KF.length-2&&h>=KF[i+1][0])i++;const A=KF[i],B=KF[i+1],t=(h-A[0])/(B[0]-A[0]);
 TOD.zen=mx3(A[1],B[1],t);TOD.hor=mx3(A[2],B[2],t);TOD.sun=mx3(A[3],B[3],t);TOD.stars=A[4]+(B[4]-A[4])*t;TOD.mtn=mx3(A[5],B[5],t);TOD.fog=mx3(A[6],B[6],t);TOD.amb=mx3(A[7],B[7],t);
 const ang=(h-6)/12*PI,el=Math.sin(ang);TOD.sunDir=nrm([Math.cos(.9)*Math.cos(ang),el,Math.sin(.9)*Math.cos(ang)]);TOD.moonDir=TOD.sunDir.map(v=>-v);
 const k=sm((el+.05)/.15);TOD.sun=TOD.sun.map(v=>v*k);TOD.night=cl(TOD.stars,0,1);TOD.floor=mx3([0,1,.8],[.6,.2,1],TOD.night*.8);TOD.ground=TOD.fog.map(v=>v*.35)}
const C255=(c,m)=>{m=m||1;const x=Math.max(c[0],c[1],c[2],1);return[c[0]/x*255*m,c[1]/x*255*m,c[2]/x*255*m].map(v=>cl(v,0,255))};
const rgb=c=>'rgb('+(cl(c[0],0,1)*255|0)+','+(cl(c[1],0,1)*255|0)+','+(cl(c[2],0,1)*255|0)+')';
// ===== FIGHTERS =====
const G_=24,JUMPV=8.4;
const MV={p1:{st:.07,en:.17,dur:.28,dmg:4,reach:1.35,kb:1.5,stun:.2,lunge:1.4,an:'p1'},p2:{st:.08,en:.18,dur:.3,dmg:5,reach:1.45,kb:1.9,stun:.24,lunge:1.7,an:'p2'},p3:{st:.12,en:.24,dur:.46,dmg:8,reach:1.5,kb:4,stun:.38,lunge:2.2,an:'p3'},k1:{st:.17,en:.3,dur:.56,dmg:9,reach:1.85,kb:3.2,stun:.36,lunge:1.2,an:'k1'}};
const HOTSEG={p1:[6,15],p2:[5,14],p3:[6,15,4],k1:[12,10,8]};
function mkF(slot,k){return{slot,k,A:ARCH[k],pos:[0,0,0],yaw:0,hp:100,max:100,en:30,state:'free',st:0,mv:null,md:null,hd:0,spawned:0,vx:0,vz:0,y:0,vy:0,air:0,block:0,stun:0,frz:0,slow:0,combo:0,cT:0,ch:0,chT:0,q:null,
 buf:{punch:0,kick:0,p1:0,p2:0,jump:0},pulse:0,burst:0,dis:0,flash:0,hot:new Float32Array(16),hotT:new Float32Array(16),in:{mx:0,mz:0,block:0,press:{punch:0,kick:0,p1:0,p2:0,jump:0}},ai:{t:0,mode:'idle',mt:0,lvl:.55,ph:0},ph:0,cloud:null,cN:0,jp:new Float32Array(54),sf:new Float32Array(168),aT:0}}
const FI=[mkF(0,0),mkF(1,1)];
function setArch(F,k){F.k=k;F.A=ARCH[k];F.max=F.hp=F.A.hp;F.cloud=null}
const ST=(F)=>{const dx=Math.sin(F.yaw),dz=Math.cos(F.yaw);return[dx,dz]};
function startAtk(F,id){F.state='atk';F.st=0;F.mv=id;F.hd=0;F.spawned=0;F.q=null;if(id==='pw1'||id==='pw2'){const pid=F.A.pw[id==='pw1'?0:1],p=PW[pid];F.en-=p.cost;F.md={pw:pid,st:p.fx,en:p.fx+.18,dur:p.dur,an:p.an}}else F.md=MV[id]}
// ---- skeleton pose (procedural). local coords: x right, y up, z forward ----
function setJoints(F,dt){const A=F.A,S=A.S,t=F.aT,sp=Math.hypot(F.vx,F.vz),amp=cl(sp/2.6,0,1),fd=ST(F);const vf=F.vx*fd[0]+F.vz*fd[1];F.ph+=dt*6.9*(1+.6*amp)*(vf<-.1?-1:1);
 const s=Math.sin(F.ph)*amp;let c=.1+.012*Math.sin(t*5.2),l=.12,tilt=0,rootY=0;
 let hR=[.2,1.18,.3],hL=[-.18,1.2,.25],fR=[.13,.04+Math.max(0,Math.sin(F.ph-.6))*.12*amp,-.2+.34*s],fL=[-.13,.04+Math.max(0,-Math.sin(F.ph-.6))*.12*amp,.2-.34*s];
 const m=F.md,u=F.st;let e=0;if(F.state==='atk'&&m)e=u<m.st?sm(u/m.st)*.6:u<m.en?1:1-sm((u-m.en)/(m.dur-m.en+1e-3));
 const L=(a,b,k)=>mx3(a,b,k);
 switch(F.state){
 case'atk':{const id=F.mv;
  if(id==='p1'){hR=L(hR,[.08,1.4,.8],e);l+=.15*e}else if(id==='p2'){hL=L(hL,[-.08,1.4,.8],e);l+=.15*e}
  else if(id==='p3'){hR=L([.5,1.3,.05],[-.2,1.34,.55],e);l+=.1*e}
  else if(id==='k1'){fR=L(fR,[.12,.95,.85],e);l-=.22*e;hL=L(hL,[-.5,1.3,.1],e)}
  else if(m&&m.an==='c'){const w=u<m.st?sm(u/m.st):1;const th=u<m.st?0:1;hR=L([.12,1.1,.08],[.1,1.3,.8],th);hL=L([-.12,1.1,.08],[-.1,1.3,.8],th);c=.3*(1-th*.5);l=.3-.1*th;void w}
  else if(m){const th=u<m.st?sm(u/m.st):1;hR=L([.15,1.1,.1],[.12,2.1,.05],th);hL=L([-.15,1.1,.1],[-.12,2.1,.05],th);rootY=.12*th;c=.3*(1-th);l=-.2*th}
  break}
 case'hit':{const k=F.air?1:cl(1-F.st/(F.stun+1e-3),0,1);hR=L(hR,[.4,1.2,-.1],k);hL=L(hL,[-.4,1.2,-.1],k);l-=.4*k;break}
