function nextTOD(){const L=[5.8,12,18.3,23];let i=0,b=99;L.forEach((h,k)=>{const d=Math.abs(h-TOD.hour);if(d<b){b=d;i=k}});setTOD(L[(i+1)%4]);status('TIME · '+todName())}
