function toggle2P(){M.twoP=!M.twoP;resetMatch();status(M.twoP?'2 PLAYER · P2 = ARROWS / PAD 2':'1 PLAYER VS CPU')}
function cycleOpp(d){M.opp=(M.opp+d+6)%6;setArch(FI[1],M.opp);resetMatch();status('OPPONENT · '+ARCH[M.opp].n)}
function cycleP1(){M.p1=(M.p1+1)%6;setArch(FI[0],M.p1);resetMatch();status('P1 · '+ARCH[M.p1].n)}
