  const f=cl(F.hp/F.max,0,1),W=Math.min(VW*.36,430);b.lv+=(f-b.lv)*Math.min(1,d*3);if(b.lv<f)b.lv=f;
  b.fill.setAttribute('width',(W*f).toFixed(1));b.fill.setAttribute('x',(s===0?b.x0+W*(1-f):b.x0).toFixed(1));b.lag.setAttribute('width',(W*b.lv).toFixed(1));b.lag.setAttribute('x',(s===0?b.x0+W*(1-b.lv):b.x0).toFixed(1));
  const ew=W*cl(F.en/100,0,1);b.en.setAttribute('width',ew.toFixed(1));b.en.setAttribute('x',(s===0?b.x0+W-ew:b.x0).toFixed(1));b.en.setAttribute('fill',F.en>=PW[F.A.pw[1]].cost?'#ffcc00':'#ff7bff');
  b.nm.textContent=(s===0?'P1 · ':(M.twoP?'P2 · ':'CPU · '))+F.A.n;b.pw.textContent=(s===0?'Y ':'')+PW[F.A.pw[0]].n+' · '+(s===0?'B ':'')+PW[F.A.pw[1]].n;b.cb.textContent=F.combo>1?F.combo+' HITS':'';
