 HUD.timer.textContent=fight?String(Math.max(0,Math.ceil(M.timer))):'';HUD.rnd.textContent=fight?'ROUND '+M.round+(M.twoP?'':' · STAGE '+M.ladder):'';HUD.msg.textContent=fight?M.msg:'';
 if(!fight){HUD.ammo.textContent=TPS.rel>0?'RELOADING':'AMMO '+TPS.ammo+'/'+TPS.max;HUD.score.textContent='SCORE '+TPS.score}
