function attach(){window.addEventListener('keydown',e=>{const k=e.code;if(k.indexOf('Arrow')===0||k==='Space'||k==='Slash'||k==='Quote')e.preventDefault();if(e.repeat)return;KEY[k]=true;if(K1[k])kb1[K1[k]]=1;if(K2[k]&&M.twoP)kb2[K2[k]]=1;
